let shapeSnap=true,shapeActive=0,shapeFrame=null;
const oldStartDraft=startDraft;
startDraft=function(){oldStartDraft();shapeActive=0;shapeFrame=null};
const edgeLetter=i=>String.fromCharCode(65+i);
function shapeSelect(i,focus=false){shapeActive=i;refreshShape();if(focus){const input=$('#shapeLength'+i);input?.focus({preventScroll:true});input?.select()}}
function shapeLength(i,value){shapeActive=i;try{if(value.trim()==='')throw Error('Wpisz długość odcinka.');const next=ShapeEdit.resize(shapeDraft.points,i,Number(value),shapeSnap),error=Geom.polygonError(next);if(error)throw Error(error);shapeDraft.points=next;refreshShape();}catch(e){$('#shapeWarning').textContent=e.message;$('#shapeLength'+i).value=Math.round(Geom.edge(shapeDraft,i).len*10)/10}}
draftChange=function(i,k,v){shapeActive=i;if(v.trim()===''||!Number.isFinite(Number(v)))return;const next=ShapeEdit.move(shapeDraft.points,i,{...shapeDraft.points[i],[k]:Number(v)},shapeSnap);shapeDraft.points=next;refreshShape()};
shapeSVG=function(){const p=shapeDraft.points,b=Geom.bounds(p),frame=shapeFrame||{s:Math.min(530/Math.max(b.w,1),250/Math.max(b.d,1)),b},s=frame.s,ox=(720-frame.b.w*s)/2,oy=65,pos=q=>[ox+(q.x-frame.b.x)*s,oy+(q.y-frame.b.y)*s];return `<svg id="shapeSvg" viewBox="0 0 720 390" data-scale="${s}" aria-label="Edytor obrysu z wymiarami"><polygon points="${p.map(q=>pos(q).join(',')).join(' ')}" fill="#e6f0f4"/>${p.map((q,i)=>{const a=pos(q),z=pos(p[(i+1)%p.length]),dx=z[0]-a[0],dy=z[1]-a[1],len=Math.hypot(dx,dy),nx=dy/(len||1),ny=-dx/(len||1),A=[a[0]+nx*28,a[1]+ny*28],B=[z[0]+nx*28,z[1]+ny*28],active=i===shapeActive,c=active?'#c66a18':'#426c87';return `<g data-shape-edge="${i}" role="button" tabindex="0" aria-label="Odcinek ${edgeLetter(i)}, ${(len/s).toFixed(1)} mm" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();shapeSelect(${i},true)}"><path d="M${a}L${z}" stroke="transparent" stroke-width="20"/><path d="M${a}L${z}" stroke="${c}" stroke-width="${active?6:3}" ${shapeDraft.edges[i].kind!=='wall'?'stroke-dasharray="8 5"':''}/><path d="M${a}L${A}L${B}L${z}" fill="none" stroke="${c}" stroke-width="1"/><text x="${(A[0]+B[0])/2}" y="${(A[1]+B[1])/2-5}" text-anchor="middle" font-size="${active?14:12}" font-weight="${active?700:500}" fill="${c}" stroke="#fff" stroke-width="4" paint-order="stroke">${edgeLetter(i)} · ${Math.round(len/s*10)/10} mm</text></g>`}).join('')}${p.map((q,i)=>{const a=pos(q),prev=p[(i+p.length-1)%p.length],next=p[(i+1)%p.length],u={x:prev.x-q.x,y:prev.y-q.y},v={x:next.x-q.x,y:next.y-q.y},ul=Math.hypot(u.x,u.y),vl=Math.hypot(v.x,v.y),right=ul&&vl&&Math.abs((u.x*v.x+u.y*v.y)/ul/vl)<.0001;const x=[u.x/ul*15,u.y/ul*15],y=[v.x/vl*15,v.y/vl*15];return `${right?`<path d="M${a[0]+x[0]},${a[1]+x[1]}l${y}l${-x[0]},${-x[1]}" fill="none" stroke="#338d80" stroke-width="1.5"/>`:''}<circle data-vertex="${i}" cx="${a[0]}" cy="${a[1]}" r="11" fill="#173d5c" stroke="white" stroke-width="2"/><text x="${a[0]}" y="${a[1]+4}" text-anchor="middle" font-size="10" fill="white" pointer-events="none">${i+1}</text>`}).join('')}</svg>`};
refreshShape=function(){if(shapeActive>=shapeDraft.points.length)shapeActive=0;if($('#shapeDrawing'))$('#shapeDrawing').innerHTML=shapeSVG();document.querySelectorAll('[data-shape-row]').forEach(row=>row.classList.toggle('active-shape-row',+row.dataset.shapeRow===shapeActive));shapeDraft.points.forEach((p,i)=>{for(const [key,value] of [['x',p.x],['y',p.y],['length',Geom.edge(shapeDraft,i).len]]){const input=document.querySelector(`[data-shape-value="${i}-${key}"]`);if(input&&input!==document.activeElement)input.value=Math.round(value*10)/10}});if($('#shapeWarning'))$('#shapeWarning').textContent=Geom.polygonError(shapeDraft.points)||`Wybrany odcinek ${edgeLetter(shapeActive)} · ${Math.round(Geom.edge(shapeDraft,shapeActive).len*10)/10} mm. ${shapeSnap?'Kąty proste są utrzymywane; powiązane odcinki zmieniają się razem.':'Przyciąganie wyłączone — swobodne skosy.'}`};
renderShape=function(){if(!shapeDraft)startDraft();shapeActive=Math.min(shapeActive,shapeDraft.points.length-1);$('#content').innerHTML=`<div class="room-heading"><div><h2>Obrys · ${esc(room().name)}</h2><p class="muted">Kliknij odcinek lub jego wymiar. Pomarańczowy odcinek odpowiada aktywnej komórce.</p></div><button onclick="view='wall';shapeDraft=null;render()">Wróć</button></div><div class="shape-presets">${[['rect','Prostokąt'],['L','Kształt L'],['U','Kształt U'],['skos','Trapez / skosy']].map(([k,t])=>`<button onclick="presetDraft('${k}')">${t}</button>`).join('')}<button onclick="rotateDraft()">↻ Obróć 90°</button></div><label class="snap-switch"><input type="checkbox" ${shapeSnap?'checked':''} onchange="shapeSnap=this.checked;refreshShape()">Przyciąganie 90° / poziom–pion</label><p class="muted">Przeciągaj narożniki. Przy włączonym przyciąganiu proste ściany zachowują kierunek; przy skosach narożnik przyciąga się do osi sąsiadów. Zmiana długości przesuwa koniec odcinka i powiązane narożniki.</p><div class="card"><div class="drawing" id="shapeDrawing" style="touch-action:none">${shapeSVG()}</div></div><div id="shapeWarning" class="edit-notice" role="status"></div><div class="card measure-scroll"><table class="shape-table"><thead><tr><th>Odcinek</th><th>Długość · mm</th><th>Narożnik</th><th>X · mm</th><th>Y · mm</th><th>Rodzaj</th><th>Otwarcie od · mm</th><th>Szer. otwarcia · mm</th><th></th></tr></thead><tbody>${shapeDraft.points.map((p,i)=>{const e=shapeDraft.edges[i];return `<tr data-shape-row="${i}"><td><button onclick="shapeSelect(${i},true)">${edgeLetter(i)} · ${i+1} → ${(i+1)%shapeDraft.points.length+1}</button></td><td><input id="shapeLength${i}" data-shape-value="${i}-length" aria-label="Długość odcinka ${edgeLetter(i)}" type="text" inputmode="text" data-dimension-math autocomplete="off" spellcheck="false" min="20" max="100000" step="0.1" value="${Math.round(Geom.edge(shapeDraft,i).len*10)/10}" onfocus="shapeSelect(${i})" onchange="shapeLength(${i},this.value)"></td><td>${i+1}</td>${['x','y'].map(k=>`<td><input data-shape-value="${i}-${k}" aria-label="Narożnik ${i+1} ${k.toUpperCase()}" type="text" inputmode="text" data-dimension-math autocomplete="off" spellcheck="false" step="1" value="${p[k]}" onfocus="shapeSelect(${i})" onchange="draftChange(${i},'${k}',this.value)"></td>`).join('')}<td><select aria-label="Rodzaj ściany ${edgeLetter(i)}" onfocus="shapeSelect(${i})" onchange="draftEdge(${i},'kind',this.value)">${[['wall','Pełna ściana'],['open','Całkowicie otwarta'],['partial','Częściowo otwarta']].map(([k,t])=>`<option value="${k}" ${e.kind===k?'selected':''}>${t}</option>`).join('')}</select></td>${['start','width'].map((k,j)=>`<td><input aria-label="${j?'Szerokość':'Początek'} otwarcia ${i+1}" type="text" inputmode="text" data-dimension-math autocomplete="off" spellcheck="false" value="${e[k]}" ${e.kind!=='partial'?'disabled':''} onfocus="shapeSelect(${i})" onchange="draftEdge(${i},'${k}',this.value)"></td>`).join('')}<td><button title="Dodaj narożnik na odcinku" onclick="insertCorner(${i})">＋</button><button title="Usuń narożnik" ${shapeDraft.points.length<=3?'disabled':''} onclick="removeCorner(${i})">×</button></td></tr>`}).join('')}</tbody></table></div><div class="shape-actions"><span class="muted">Zastosuj obrys, aby zapisać zmiany. X w prawo, Y w dół.</span><button onclick="startDraft();renderShape()">Odrzuć szkic</button><button class="primary" onclick="applyShape()">Zastosuj obrys</button></div>`;bindShapeDrag();refreshShape()};
bindShapeDrag=function(){const host=$('#shapeDrawing');let drag;host.onpointerdown=ev=>{const vertex=ev.target.closest('[data-vertex]');if(!vertex){const edge=ev.target.closest('[data-shape-edge]');if(edge)shapeSelect(+edge.dataset.shapeEdge,true);return}ev.preventDefault();const svg=$('#shapeSvg'),matrix=svg.getScreenCTM().inverse(),pt=new DOMPoint(ev.clientX,ev.clientY).matrixTransform(matrix),i=+vertex.dataset.vertex;shapeActive=i;shapeFrame={b:Geom.bounds(shapeDraft.points),s:+svg.dataset.scale};drag={i,pt,matrix,original:copy(shapeDraft.points)};host.setPointerCapture(ev.pointerId);refreshShape()};host.onpointermove=ev=>{if(!drag)return;const p=new DOMPoint(ev.clientX,ev.clientY).matrixTransform(drag.matrix),q=drag.original[drag.i];shapeDraft.points=ShapeEdit.move(drag.original,drag.i,{x:Math.round(q.x+(p.x-drag.pt.x)/shapeFrame.s),y:Math.round(q.y+(p.y-drag.pt.y)/shapeFrame.s)},shapeSnap,12/shapeFrame.s);refreshShape()};const end=ev=>{if(!drag)return;if(ev.type==='pointercancel'||Geom.polygonError(shapeDraft.points)){shapeDraft.points=drag.original;toast('Przywrócono narożnik — ruch anulowany lub niepoprawny obrys.')}drag=null;shapeFrame=null;refreshShape()};host.onpointerup=end;host.onpointercancel=end};
